export default function Home() {
  const [view,setView]=useState<"Biblioteca"|"Plan"|"Favoritas">("Biblioteca");
  const [level,setLevel]=useState("Todos");
  const [category,setCategory]=useState<"Todas"|Category>("Todas");
  const [query,setQuery]=useState("");
  const [activeLesson,setActiveLesson]=useState<Lesson|null>(null);
  const [newsIndex,setNewsIndex]=useState(0);
  const [newsPaused,setNewsPaused]=useState(false);
  const [favoriteIds,setFavoriteIds]=useState<number[]>([]);
  const [planIds,setPlanIds]=useState<number[]>([]);
  const [storageReady,setStorageReady]=useState(false);
  const [sidebarOpen,setSidebarOpen]=useState(false);
  const [levelMenuOpen,setLevelMenuOpen]=useState(false);
  const [openLevelGroup,setOpenLevelGroup]=useState<string|null>(null);
  const openLesson=(lesson:Lesson)=>{if(lesson.path){window.location.assign(lesson.path)}else if(lesson.special){window.location.assign("/choose-conversation")}else{setActiveLesson(lesson)}};
  const surprise=()=>{const previous=Number(window.sessionStorage.getItem("chespanish-last-surprise"));const pool=lessons.filter(lesson=>lesson.id!==previous);const randomValue=new Uint32Array(1);window.crypto.getRandomValues(randomValue);const chosen=pool[randomValue[0]%pool.length]||lessons[0];window.sessionStorage.setItem("chespanish-last-surprise",String(chosen.id));openLesson(chosen)};
  const filtered=useMemo(()=>filterLessons(lessons,{level,category,query}) as Lesson[],[level,category,query]);
  const visibleLessons=view==="Favoritas"?filtered.filter(lesson=>favoriteIds.includes(lesson.id)):filtered;
  const plannedLessons=planIds.map(id=>lessons.find(lesson=>lesson.id===id)).filter((lesson):lesson is Lesson=>Boolean(lesson));
  const news=latestNews[newsIndex];
  const newsArtwork = news.lessonId===101?"/conversation-worlds/elimination-machine.webp":news.lessonId===102?"/conversation-worlds/absurd-universe.webp":null;
  const scrollToResults=()=>window.requestAnimationFrame(()=>document.getElementById("library-results")?.scrollIntoView({behavior:"smooth",block:"start"}));
  const chooseLevel=(nextLevel:string)=>{setView("Biblioteca");setLevel(nextLevel);setSidebarOpen(false);scrollToResults()};
  const chooseCategory=(nextCategory:"Todas"|Category)=>{setView("Biblioteca");setCategory(nextCategory);scrollToResults()};
  const openView=(nextView:"Biblioteca"|"Plan"|"Favoritas")=>{setView(nextView);setLevel("Todos");setCategory("Todas");setQuery("");setSidebarOpen(false);scrollToResults()};
  const toggleFavorite=(id:number)=>setFavoriteIds(ids=>ids.includes(id)?ids.filter(item=>item!==id):[...ids,id]);
  const togglePlan=(id:number)=>setPlanIds(ids=>ids.includes(id)?ids.filter(item=>item!==id):[...ids,id]);
  useEffect(()=>{if(newsPaused)return;const timer=window.setInterval(()=>setNewsIndex(index=>(index+1)%latestNews.length),5200);return()=>window.clearInterval(timer)},[newsPaused]);
  useEffect(()=>{const timer=window.setTimeout(()=>{try{setFavoriteIds(JSON.parse(window.localStorage.getItem("chespanish-favorites")||"[]"));setPlanIds(JSON.parse(window.localStorage.getItem("chespanish-plan")||"[]"))}catch{}setStorageReady(true)},0);return()=>window.clearTimeout(timer)},[]);
  useEffect(()=>{if(!storageReady)return;window.localStorage.setItem("chespanish-favorites",JSON.stringify(favoriteIds));window.localStorage.setItem("chespanish-plan",JSON.stringify(planIds))},[favoriteIds,planIds,storageReady]);
  useEffect(()=>{const onKey=(event:KeyboardEvent)=>{if(event.key==="Escape")setSidebarOpen(false)};window.addEventListener("keydown",onKey);return()=>window.removeEventListener("keydown",onKey)},[]);
  const lessonGrid=(items:Lesson[],planned=false)=>items.length?<div className="lesson-grid">{items.map((l,i)=><article className={`lesson-card accent-${l.level.toLowerCase()} ${l.special?"special-card":""}`} key={l.id} onClick={()=>openLesson(l)}>{l.image&&<img className="conversation-lesson-thumb" src={l.image} alt="" loading="lazy" width="1672" height="941"/>}<div className="card-top"><span className="level-badge">{l.displayLevel||l.level}</span><div className="card-actions"><button className={favoriteIds.includes(l.id)?"saved":""} aria-label={favoriteIds.includes(l.id)?`Quitar ${l.title} de favoritas`:`Guardar ${l.title} en favoritas`} title="Favorita" onClick={event=>{event.stopPropagation();toggleFavorite(l.id)}}>{favoriteIds.includes(l.id)?"★":"☆"}</button><button className={planIds.includes(l.id)?"saved":""} aria-label={planIds.includes(l.id)?`Quitar ${l.title} del plan`:`Agregar ${l.title} al plan`} title="Plan de clase" onClick={event=>{event.stopPropagation();togglePlan(l.id)}}>{planIds.includes(l.id)?"✓":"＋"}</button></div></div>{planned&&<span className="plan-position">{String(i+1).padStart(2,"0")}</span>}<div className="card-icon">{l.category==="Gramática"?"Aa":l.category==="Escucha"?"♫":l.category==="Fonética"?"ɾ":l.category==="Vocabulario"?"Ab":"“ ”"}</div><span className="category-name">{l.category}</span><h3>{l.title}</h3><p>{l.subtitle}</p><div className="card-bottom"><span>◷ {l.duration}</span><span>{l.tag}</span>{l.path?<a className="card-open" href={l.path} onClick={event=>event.stopPropagation()} aria-label={`Abrir ${l.title}`}>ABRIR →</a>:<b>→</b>}</div>{!planned&&view==="Biblioteca"&&i===0&&<span className="ready-marker">LISTA</span>}</article>)}</div>:<div className="empty-state">{view!=="Biblioteca"&&<img className="empty-mascot" src={view==="Plan"?"/mascots/teacher.png":"/mascots/mate.png"} alt="" />}<span>{view==="Plan"?"▣":view==="Favoritas"?"☆":"⌕"}</span><h3>{view==="Plan"?"Tu plan está vacío":view==="Favoritas"?"Todavía no guardaste favoritas":"No encontré esa clase"}</h3><p>{view==="Plan"?"Volvé a Mi biblioteca y tocá ＋ en las clases que quieras preparar.":view==="Favoritas"?"Tocá la estrella de cualquier clase para encontrarla acá.":"Probá con otra palabra o cambiá los filtros."}</p>{view!=="Biblioteca"&&<button onClick={()=>openView("Biblioteca")}>Ir a Mi biblioteca</button>}</div>;
  return <div className="app-shell">
    <button className={`sidebar-scrim ${sidebarOpen?"visible":""}`} aria-label="Cerrar menú" onClick={()=>setSidebarOpen(false)} />
    <aside className={`sidebar ${sidebarOpen?"open":""}`} aria-hidden={!sidebarOpen}>
      <div className="sidebar-head"><div className="brand"><span className="brand-avatar" aria-hidden="true"><img src="/mascots/mate.png" alt="" /></span><div><b>CHE</b>SPANISH<small>TEACHER STUDIO</small></div></div><button className="sidebar-close" onClick={()=>setSidebarOpen(false)} aria-label="Cerrar menú">×</button></div>
      <nav className="main-nav" aria-label="Navegación principal">
        <button className={`nav-item ${view==="Biblioteca"?"active":""}`} onClick={()=>openView("Biblioteca")} aria-current={view==="Biblioteca"?"page":undefined}><span className="nav-glyph nav-library" /> Mi biblioteca</button>
        <button className={`nav-item ${view==="Plan"?"active":""}`} onClick={()=>openView("Plan")} aria-current={view==="Plan"?"page":undefined}><span className="nav-glyph nav-plan" /> Plan de clase <b>{planIds.length||""}</b></button>
        <button className={`nav-item ${view==="Favoritas"?"active":""}`} onClick={()=>openView("Favoritas")} aria-current={view==="Favoritas"?"page":undefined}><span className="nav-glyph nav-star" /> Favoritas <b>{favoriteIds.length||""}</b></button>
      </nav>
      <p className="side-label">CONTENIDOS</p>
      <div className="level-explorer">
        <button className={`all-lessons-toggle ${levelMenuOpen?"expanded":""}`} onClick={()=>setLevelMenuOpen(open=>!open)} aria-expanded={levelMenuOpen}><span className="all-grid"><i/><i/><i/><i/></span><div><b>Todas las clases</b><small>{category==="Todas"?`${lessons.length} experiencias listas`:category}</small></div><i className="level-chevron">⌄</i></button>
        {levelMenuOpen&&<div className="level-groups">
          {levelGroups.map(group=><section key={group.id} className={`level-group group-${group.id}`}>
            <button onClick={()=>setOpenLevelGroup(current=>current===group.id?null:group.id)} aria-expanded={openLevelGroup===group.id}><span/><div><b>{group.label}</b><small>{group.copy}</small></div><i>{openLevelGroup===group.id?"−":"+"}</i></button>
            {openLevelGroup===group.id&&<div className="level-subnav">{group.levels.map(item=><button key={item} className={level===item?"selected":""} onClick={()=>chooseLevel(item)}><span className={`level-dot level-${item.toLowerCase()}`}>{item}</span><div><b>{levelNames[item]}</b><small>Nivel {item}</small></div><strong>{filterLessons(lessons,{level:item,category,query}).length}</strong></button>)}</div>}
          </section>)}
          <button className={`a0-entry ${level==="A0"?"selected":""}`} onClick={()=>chooseLevel("A0")}><span className="level-dot level-a0">A0</span><div><b>Primeros pasos</b><small>Antes del recorrido A1</small></div><strong>{filterLessons(lessons,{level:"A0",category,query}).length}</strong></button>
          <button className={`all-entry ${level==="Todos"?"selected":""}`} onClick={()=>chooseLevel("Todos")}><span>∞</span><b>Todos los niveles{category!=="Todas"?` · ${category}`:""}</b></button>
        </div>}
      </div>
      <div className="mate-tip"><span className="tip-orbit"><i/><b>CH</b></span><div><b>Tu biblioteca crece</b><p>Nuevos mundos, ordenados por nivel y listos para enseñar.</p></div></div>
      <div className="profile"><span>AN</span><div><b>Alejandro</b><small>Profesor</small></div><button aria-label="Opciones de perfil">•••</button></div>
    </aside>
    <main className="main-content">
      <header className="topbar"><button className="menu-trigger" onClick={()=>setSidebarOpen(true)} aria-label="Abrir menú" aria-expanded={sidebarOpen}><i/><i/><i/></button><a className="topbar-brand" href="/">CHESPANISH</a><div className="search"><span>⌕</span><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Buscar tema, objetivo o palabra clave…"/><kbd>⌘ K</kbd></div><button className="new-button surprise-button" onClick={surprise} aria-label="Abrir una clase aleatoria diferente"><span>✦</span> ¡SORPRENDEME!</button></header>
      <section className={`news-carousel news-theme-${newsIndex}`} aria-label="Novedades y nuevas clases" onMouseEnter={()=>setNewsPaused(true)} onMouseLeave={()=>setNewsPaused(false)} onFocus={()=>setNewsPaused(true)} onBlur={e=>{if(!e.currentTarget.contains(e.relatedTarget as Node))setNewsPaused(false)}}>
        <div className="news-head"><span><i/> NOVEDADES</span><b>{String(newsIndex+1).padStart(2,"0")} / {String(latestNews.length).padStart(2,"0")}</b></div>
        <div className="news-slide" key={news.title}>
          <div className="news-copy"><div className="news-labels"><span>{news.kicker}</span><em>{news.route}</em></div><h2>{news.title}</h2><p>{news.copy}</p><button onClick={()=>openLesson(lessons.find(lesson=>lesson.id===news.lessonId)!)}>Abrir esta clase <span>→</span></button></div>
          {newsArtwork?<div className="conversation-news-art" aria-hidden="true"><img src={newsArtwork} alt="" width="1672" height="941"/></div>:<div className="news-brain" aria-hidden="true"><span className="news-word word-one">{news.words[0]}</span><span className="news-word word-two">{news.words[1]}</span><span className="news-word word-three">{news.words[2]}</span><div className="news-core">{news.symbol}</div><img src={newsMascots[newsIndex%newsMascots.length]} alt="" /></div>}
        </div>
        <div className="news-controls"><button aria-label="Novedad anterior" onClick={()=>setNewsIndex(index=>(index-1+latestNews.length)%latestNews.length)}>←</button><div>{latestNews.map((item,index)=><button key={item.title} className={index===newsIndex?"active":""} aria-label={`Ver ${item.title}`} aria-pressed={index===newsIndex} onClick={()=>setNewsIndex(index)}/>)}</div><button aria-label="Novedad siguiente" onClick={()=>setNewsIndex(index=>(index+1)%latestNews.length)}>→</button></div>
        <div className="news-progress" key={`progress-${newsIndex}`}><i/></div>
      </section>
      <section className="welcome"><div><p className="eyebrow">TU ESPACIO DE CLASES</p><h1>¿Qué vamos a enseñar hoy?</h1><p>Todo tu español real, organizado y listo para abrir frente al alumno.</p></div><div className="quick-stats"><div><b>{lessons.length}</b><span>clases listas</span></div><div><b>7</b><span>niveles</span></div><div><b>5</b><span>rutas</span></div></div></section>
      <section className="spotlight b1-conversation-spotlight"><div className="spotlight-copy"><span className="featured-pill">DOS NUEVAS CLASES · CONVERSACIÓN B1</span><h2>¿Qué cambiarías del mundo?</h2><p>Una máquina que elimina cosas para siempre. Una ciudad donde las reglas dejan de tener sentido. Elegí, descubrí el giro y defendé tu opinión.</p><div className="meta"><span>B1</span><span>30 decisiones + 15 reglas</span><span>Español rioplatense</span></div><a className="b1-spotlight-link" href="/la-maquina-que-elimina-cosas">Abrir la máquina <span>→</span></a><a className="b1-spotlight-secondary" href="/tu-vida-con-una-regla-absurda">Explorar las reglas absurdas →</a></div><div className="guide-art" aria-hidden="true"><img src="/conversation-worlds/elimination-machine.webp" alt="" /></div></section>
      <section className="library-heading" id="library-results"><div><p className="eyebrow">{view==="Biblioteca"?"BIBLIOTECA":view==="Plan"?"TU PRÓXIMA CLASE":"COLECCIÓN PERSONAL"}</p><h2>{view==="Plan"?"Plan de clase":view==="Favoritas"?"Favoritas":level==="Todos"?"Todas las clases":`${level} · ${levelNames[level]}`}</h2></div>{view==="Biblioteca"&&<button className={`show-all ${category==="Todas"?"active":""}`} onClick={()=>chooseCategory("Todas")}>Ver todas las clases</button>}</section>
      {view==="Biblioteca"&&<section className="combined-filters" aria-label="Filtros combinados de clases">
        <label>Nivel<select value={level} onChange={event=>chooseLevel(event.target.value)}><option value="Todos">Todos los niveles</option>{Object.keys(levelNames).map(item=><option value={item} key={item}>{item} · {levelNames[item]}</option>)}</select></label>
        <label>Categoría<select value={category} onChange={event=>chooseCategory(event.target.value as "Todas"|Category)}><option value="Todas">Todas las categorías</option>{(["Gramática","Conversación","Escucha","Fonética","Vocabulario"] as Category[]).map(item=><option value={item} key={item}>{item}</option>)}</select></label>
        <div className="filter-result" role="status" aria-live="polite"><strong>{filtered.length} {filtered.length===1?"clase":"clases"}</strong><span>{level==="Todos"?"Todos los niveles":level} · {category==="Todas"?"Todas las categorías":category}</span></div>
        {(level!=="Todos"||category!=="Todas"||query)&&<button onClick={()=>{setLevel("Todos");setCategory("Todas");setQuery("")}}>Limpiar filtros</button>}
      </section>}
      {view==="Biblioteca"&&<section className="route-divider" aria-label="Elegir entre gramática, conversación, escucha, fonética y vocabulario">
        <button className={`route-card grammar-route ${category==="Gramática"?"active":""}`} onClick={()=>chooseCategory("Gramática")} aria-pressed={category==="Gramática"}><span className="route-mascot"><img src="/mascots/grammar.png" alt="" /></span><div><small>RUTA 01</small><b>GRAMÁTICA</b><em>Patrones, estructuras y práctica clara</em></div><i>{filterLessons(lessons,{level,category:"Gramática",query}).length} clases</i></button>
        <button className={`route-card conversation-route ${category==="Conversación"?"active":""}`} onClick={()=>chooseCategory("Conversación")} aria-pressed={category==="Conversación"}><span className="route-mascot"><img src="/mascots/conversation.png" alt="" /></span><div><small>RUTA 02</small><b>CONVERSACIÓN</b><em>Hablar, reaccionar y conectar de verdad</em></div><i>{filterLessons(lessons,{level,category:"Conversación",query}).length} clases</i></button>
        <button className={`route-card listening-route ${category==="Escucha"?"active":""}`} onClick={()=>chooseCategory("Escucha")} aria-pressed={category==="Escucha"}><span className="route-mascot"><img src="/mascots/headphones.png" alt="" /></span><div><small>RUTA 03</small><b>ESCUCHA</b><em>Oír, captar y comprender voces reales</em></div><i>{filterLessons(lessons,{level,category:"Escucha",query}).length} clase</i></button>
        <button className={`route-card phonetics-route ${category==="Fonética"?"active":""}`} onClick={()=>chooseCategory("Fonética")} aria-pressed={category==="Fonética"}><span className="route-symbol route-mouth" aria-hidden="true"><i/><b/><i/></span><div><small>RUTA 04</small><b>FONÉTICA</b><em>Ver, colocar y entrenar cada sonido</em></div><i>{filterLessons(lessons,{level,category:"Fonética",query}).length} clase</i></button>
        <button className={`route-card vocabulary-route ${category==="Vocabulario"?"active":""}`} onClick={()=>chooseCategory("Vocabulario")} aria-pressed={category==="Vocabulario"}><span className="route-symbol route-vocabulary" aria-hidden="true"><i/><i/><i/></span><div><small>RUTA 05</small><b>VOCABULARIO</b><em>Palabras, chunks y español que se usa</em></div><i>{filterLessons(lessons,{level,category:"Vocabulario",query}).length} clase</i></button>
      </section>}
      {view==="Biblioteca"&&(category==="Todas"||category==="Gramática")&&<section className="curriculum-strip"><div><span>RUTA GRAMATICAL · CERVANTES</span><h3>Del primer sustantivo al dominio C2</h3><p>Un programa continuo, convertido en mundos visuales y clases enseñables.</p></div><nav><button onClick={()=>chooseLevel("A1")}><small>BÁSICO</small><b>A1 · A2</b></button><button onClick={()=>chooseLevel("B1")}><small>INTERMEDIO</small><b>B1 · B2</b></button><button onClick={()=>chooseLevel("C1")}><small>AVANZADO</small><b>C1 · C2</b></button></nav><a href="/la-fabrica-de-los-nombres">EMPEZAR EN A1 →</a></section>}
      {view==="Plan"&&plannedLessons.length>0&&<div className="plan-summary"><img src="/mascots/teacher.png" alt="" /><div><b>{plannedLessons.length} {plannedLessons.length===1?"clase preparada":"clases preparadas"}</b><p>El orden de abajo es el orden en que las agregaste. Abrí una clase o quitála con ✓.</p></div><button onClick={()=>setPlanIds([])}>Vaciar plan</button></div>}
      {lessonGrid(view==="Plan"?plannedLessons:visibleLessons,view==="Plan")}
    </main>
    {activeLesson&&<div className="modal-backdrop" onMouseDown={()=>setActiveLesson(null)}><section className="lesson-viewer" onMouseDown={e=>e.stopPropagation()} role="dialog"><header className={`viewer-header accent-${activeLesson.level.toLowerCase()}`}><button className="close" onClick={()=>setActiveLesson(null)}>×</button><div className="viewer-brand">CHESPANISH · MODO CLASE</div><div className="viewer-title"><span>{activeLesson.level}</span><div><p>{activeLesson.category}</p><h2>{activeLesson.title}</h2><small>{activeLesson.subtitle}</small></div></div><div className="viewer-meta"><span>◷ {activeLesson.duration}</span><span>◎ {activeLesson.tag}</span><span>✓ Lista para enseñar</span></div></header><div className="viewer-body">
      <section className="objective-box"><div>01</div><article><span>OBJETIVOS DE HOY</span><h3>Al final de la clase, el alumno puede…</h3><ul>{activeLesson.goals.map(x=><li key={x}>✓ {x}</li>)}</ul></article></section>
      <section className="lesson-section"><div className="section-number">02</div><article><span>ACTIVACIÓN · 5 MIN</span><h3>Empezamos hablando</h3><p>{activeLesson.warmup}</p><div className="teacher-note">💡 <b>Nota para vos:</b> no corrijas todavía. Escuchá qué recursos ya tiene el alumno.</div></article></section>
      <section className="lesson-section"><div className="section-number">03</div><article><span>CLAVE DEL TEMA</span><h3>La idea simple</h3><p className="big-explanation">{activeLesson.explanation}</p></article></section>
      <section className="lesson-section"><div className="section-number">04</div><article><span>PRÁCTICA GUIADA</span><h3>Completá y justificá</h3><div className="exercise-grid">{activeLesson.practice.map((x,i)=><div key={x}><b>{i+1}</b><p>{x}</p><button onClick={e=>{e.currentTarget.textContent=e.currentTarget.textContent==="Ver pista"?"Pensá en el contexto":"Ver pista"}}>Ver pista</button></div>)}</div></article></section>
      <section className="lesson-section speaking-section"><div className="section-number">05</div><article><span>AHORA HABLAMOS</span><h3>De práctica a conversación real</h3><div className="prompt-list">{activeLesson.speaking.map((x,i)=><div key={x}><span>{["🗣️","🎭","⚡"][i]}</span><p><b>Ronda {i+1}</b>{x}</p></div>)}</div></article></section>
      <section className="homework"><span>↗</span><div><small>PARA SEGUIR</small><h3>Tarea breve</h3><p>{activeLesson.homework}</p></div></section></div><footer className="viewer-footer"><span>CHESPANISH · Español real para conversaciones reales</span><button onClick={()=>window.print()}>⤓ Imprimir clase</button></footer></section></div>}
  </div>;
}
